import React, { useState } from 'react';
import { db } from '../data/db';

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [mensaje, setMensaje] = useState('');

  const guardarLocal = async (e) => {
    e.preventDefault();
    await db.pedidos.add({
      ...formData,
      sincronizado: 0,
      fecha: new Date().toISOString()
    });
    setMensaje("✔ Pedido guardado en el dispositivo (Offline)");
    setFormData({ cliente: '', producto: '', cantidad: 1 });
    setTimeout(() => setMensaje(''), 3000);
  };

  return (
    <div style={{ padding: '20px', maxWidth: '400px' }}>
      <h2>Nuevo Pedido</h2>
      <form onSubmit={guardarLocal} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input type="text" placeholder="Cliente" value={formData.cliente} 
          onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        <input type="text" placeholder="Producto" value={formData.producto}
          onChange={e => setFormData({...formData, producto: e.target.value})} required />
        <input type="number" value={formData.cantidad}
          onChange={e => setFormData({...formData, cantidad: e.target.value})} min="1" />
        <button type="submit" style={{ background: '#28a745', color: 'white', border: 'none', padding: '10px' }}>
          GUARDAR OFFLINE
        </button>
      </form>
      {mensaje && <p style={{ color: 'green', marginTop: '10px' }}>{mensaje}</p>}
    </div>
  );
};
